// Cloudflare Pages Function: 301 legacy /guide/<slug> URLs to their /<silo>/<slug> page.
// The map is generated by scripts/cf-routing.mjs after every build. Anything not in the
// map (e.g. /guide/all) falls through to the static file.
import map from "./_guide-redirects.json";

export function onRequestGet({ params, request, next }) {
  const hit = map[params.slug];
  if (!hit) return next();
  return Response.redirect(new URL(hit.to, request.url).toString(), hit.status);
}

export const onRequestHead = onRequestGet;
